/// <summary>
/// Extension of the class <c>LedgerAllocationRequest</c>
/// </summary>
[ExtensionOf(classStr(LedgerAllocationRequest))]
internal final class AVALedgerAllocationRequestCls_Extension
{
    static private LedgerAllocationRequest ledgerAllocationRequest_bec;

    private boolean copiedWithDifLayer_bec;
    //private boolean copyToCostAllocationJournal_bec;
    private boolean postedWithDifLayer_bec;
    private boolean summarizeValues_bec;
    private boolean ruleArc_bec;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        copiedWithDifLayer_bec,
        //copyToCostAllocationJournal_bec,
        postedWithDifLayer_bec,
        summarizeValues_bec,
        ruleArc_bec
    #endmacro

}

