/// <summary>
/// Extension of the method <m>run</m>
/// </summary>
public void run()
{
    try
    {
        ledgerAllocationRequest_bec = this;
        next run();
    }
    finally
    {
        ledgerAllocationRequest_bec = null;
    }
}

/// <summary>
/// Extension of the method <m>pack</m>
/// </summary>
/// <returns>container</returns>
public container pack()
{
    container packedClass = next pack();
    return SysPackExtensions::appendExtension(packedClass, classStr(AVALedgerAllocationRequestCls_Extension), this.pack_bec());
}

/// <summary>
/// pack method for the class
/// </summary>
/// <returns>container</returns>
private container pack_bec()
{
    return [#CurrentVersion, #CurrentList];
}

/// <summary>
/// Extension of the method <m>unpack</m>
/// </summary>
/// <param name = "_packedClass">packed class</param>
/// <returns>boolean</returns>
public boolean unpack(container _packedClass)
{
    boolean result = next unpack(_packedClass);

    if (result)
    {
        container state_bec = SysPackExtensions::findExtension(_packedClass, classStr(AVALedgerAllocationRequestCls_Extension));
        //Also unpack the extension
        if (!this.unpack_bec(state_bec))
        {
            result = false;
        }
    }

    return result;
}

/// <summary>
/// unpack method for the class
/// </summary>
/// <param name = "packedClass">packed class</param>
/// <returns>boolean</returns>
private boolean unpack_bec(container packedClass)
{
    Integer version = RunBase::getVersion(packedClass);
    switch (version)
    {
        case #CurrentVersion:
            [version, #currentList] = packedClass;
            break;
        default:
            return false;
    }
    return true;
}

